(function () {
  var MATCHES_API_URL = '';            // e.g. 'https://your-worker.workers.dev/api/matches'
  var REFRESH_MS = 60 * 1000;          // refresh live scores every minute

  var container = document.getElementById('matches-api-container');
  var dateEl = document.getElementById('fixtures-date');
  if (!container) return;

  try {
    dateEl.textContent = new Intl.DateTimeFormat('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date());
  } catch (e) {}

  if (!MATCHES_API_URL) return;        // demo mode: keep the static cards

  // Map your API's fields to the card fields (adapt here if needed)
  function mapMatch(m) {
    return {
      league: m.league || '',
      round: m.round || '',
      status: m.status || 'upcoming',
      statusText: m.statusText || '',
      time: m.time || '--:--',
      scoreHome: m.score && m.score.home != null ? m.score.home : 0,
      scoreAway: m.score && m.score.away != null ? m.score.away : 0,
      home: { name: (m.home && m.home.name) || '', logo: (m.home && m.home.logo) || '' },
      away: { name: (m.away && m.away.name) || '', logo: (m.away && m.away.logo) || '' },
      channel: m.channel || '',
      commentator: m.commentator || '',
      url: m.url || ''
    };
  }

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text != null) node.textContent = String(text);
    return node;
  }

  function teamNode(team) {
    var wrap = el('div', 'team');
    var logo = el('span', 'team__logo');
    if (/^https?:\/\//i.test(team.logo)) {
      var img = document.createElement('img');
      img.src = team.logo;
      img.alt = team.name;
      img.loading = 'lazy';
      img.referrerPolicy = 'no-referrer';
      img.onerror = function () { logo.textContent = team.name.slice(0, 2); };
      logo.appendChild(img);
    } else {
      logo.textContent = team.name.slice(0, 2);
    }
    wrap.appendChild(logo);
    wrap.appendChild(el('span', 'team__name', team.name));
    return wrap;
  }

  var STATUS_TEXT = { live: 'مباشر', upcoming: 'لم تبدأ', finished: 'انتهت' };

  function matchCard(m) {
    var safeUrl = /^https?:\/\//i.test(m.url) ? m.url : '';
    var card = el(safeUrl ? 'a' : 'div', 'match-card' + (m.status === 'live' ? ' match-card--live' : m.status === 'finished' ? ' match-card--finished' : ''));
    if (safeUrl) card.href = safeUrl;

    var top = el('div', 'match-card__top');
    top.appendChild(el('span', 'match-card__league', m.league));
    top.appendChild(el('span', '', m.round));
    card.appendChild(top);

    var body = el('div', 'match-card__body');
    body.appendChild(teamNode(m.home));                       // RTL: right
    var center = el('div', 'match-center');
    if (m.status === 'upcoming') center.appendChild(el('span', 'match-time', m.time));
    else {
      var score = el('span', 'match-score');           // home first = home team's side
      score.appendChild(el('span', '', m.scoreHome));
      score.appendChild(el('span', 'sep', '-'));
      score.appendChild(el('span', '', m.scoreAway));
      center.appendChild(score);
    }
    center.appendChild(el('span', 'match-status', m.statusText || STATUS_TEXT[m.status] || ''));
    body.appendChild(center);
    body.appendChild(teamNode(m.away));                       // RTL: left
    card.appendChild(body);

    if (m.channel || m.commentator) {
      var bottom = el('div', 'match-card__bottom');
      if (m.channel) bottom.appendChild(el('span', '', m.channel));
      if (m.commentator) bottom.appendChild(el('span', '', m.commentator));
      card.appendChild(bottom);
    }
    return card;
  }

  function showSkeleton() {
    container.textContent = '';
    for (var i = 0; i < 4; i++) container.appendChild(el('div', 'match-skeleton'));
  }
  function showMessage(text) {
    container.textContent = '';
    container.appendChild(el('div', 'match-message', text));
  }
  function render(list) {
    if (!list.length) { showMessage('لا توجد مباريات اليوم.'); return; }
    var frag = document.createDocumentFragment();
    list.forEach(function (m) { frag.appendChild(matchCard(m)); });
    container.textContent = '';
    container.appendChild(frag);
  }

  var firstLoad = true;
  function load() {
    if (firstLoad) showSkeleton();
    var ctrl = typeof AbortController === 'function' ? new AbortController() : null;
    var timer = setTimeout(function () { if (ctrl) ctrl.abort(); }, 10000);
    fetch(MATCHES_API_URL, { headers: { Accept: 'application/json' }, signal: ctrl ? ctrl.signal : undefined })
      .then(function (res) { if (!res.ok) throw new Error('HTTP ' + res.status); return res.json(); })
      .then(function (data) {
        var list = (data && Array.isArray(data.matches) ? data.matches : []).map(mapMatch);
        render(list);
      })
      .catch(function () {
        if (firstLoad) showMessage('تعذّر تحميل المباريات حاليًا. سنحاول مجددًا بعد قليل.');
      })
      .then(function () { clearTimeout(timer); firstLoad = false; });
  }

  load();
  setInterval(function () { if (!document.hidden) load(); }, REFRESH_MS);
})();
//
